arguments.new_string:
.promo-banner {
  background: var(--dark);
  color: var(--white);
  padding: 0.6rem 1rem;
  text-align: center;
  font-size: 0.875rem;
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0.75rem;
}
.promo-banner .countdown { font-weight: 700; color: var(--primary); }
.promo-banner .close-btn {
  position: absolute; right: 1rem; top: 50%; transform: translateY(-50%);
  color: var(--gray-400); font-size: 1.25rem; line-height: 1;
  transition: color var(--transition);
}
.promo-banner .close-btn:hover { color: var(--white); }
.promo-banner.hidden { display: none; }

/* ===== HEADER ===== */
.site-header {
  background: var(--white);
  border-bottom: 1px solid var(--gray-200);
  position: sticky; top: 0; z-index: 100;
}
.header-inner {
  display: flex; align-items: center; justify-content: space-between;
  padding: 0.75rem 1.5rem; max-width: var(--max-width); margin: 0 auto;
}
.logo { font-size: 1.35rem; font-weight: 700; color: var(--dark); letter-spacing: -0.02em; }
.logo span { color: var(--primary); }
.nav-links { display: flex; align-items: center; gap: 1.75rem; }
.nav-links a {
  font-size: 0.9rem; font-weight: 500; color: var(--gray-700);
  transition: color var(--transition); position: relative;
}
.nav-links a:hover, .nav-links a.active { color: var(--dark); }
.nav-links a.active::after {
  content: ''; position: absolute; bottom: -0.5rem; left: 0; right: 0;
  height: 2px; background: var(--primary); border-radius: 1px;
}
.header-actions { display: flex; align-items: center; gap: 1rem; }
.search-btn {
  display: flex; align-items: center; gap: 0.4rem;
  padding: 0.5rem 0.75rem; border-radius: var(--radius);
  border: 1px solid var(--gray-200); font-size: 0.85rem; color: var(--gray-500);
  transition: border-color var(--transition);
}
.search-btn:hover { border-color: var(--gray-400); }
.btn-login {
  font-size: 0.875rem; font-weight: 500; color: var(--dark);
  padding: 0.5rem 1rem; border-radius: var(--radius);
  transition: background var(--transition);
}
.btn-login:hover { background: var(--gray-100); }
.btn-join {
  font-size: 0.875rem; font-weight: 600; color: var(--white);
  background: var(--primary); padding: 0.5rem 1.25rem;
  border-radius: var(--radius); transition: background var(--transition);
}
.btn-join:hover { background: var(--primary-hover); }
.mobile-menu-btn { display: none; font-size: 1.5rem; color: var(--dark); }

/* PLACEHOLDER_HERO */

