.promo-banner {
  background: var(--dark);
  color: var(--white);
  padding: 0.6rem 1rem;
  text-align: center;
  font-size: 0.875rem;
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0.75rem;
}
.promo-banner .countdown { font-weight: 700; color: var(--primary); }
