/* ===== HERO CAROUSEL ===== */
.hero-carousel {
  position: relative; overflow: hidden;
  background: linear-gradient(135deg, #1a1a2e 0%, #16213e 50%, #0f3460 100%);
  color: var(--white);
}
.hero-track { display: flex; transition: transform 500ms ease; }
.hero-slide {
  min-width: 100%; display: flex; align-items: center;
  padding: 4rem 2rem; gap: 3rem;
}
.hero-slide .slide-content { flex: 1; max-width: 550px; margin: 0 auto; padding-left: 2rem; }
.hero-slide .slide-content .badge {
  display: inline-flex; align-items: center; gap: 0.4rem;
  background: rgba(255,255,255,0.12); padding: 0.35rem 0.75rem;
  border-radius: 2rem; font-size: 0.75rem; font-weight: 600;
  text-transform: uppercase; letter-spacing: 0.05em; margin-bottom: 1rem;
}
.hero-slide h2 { font-size: 2.25rem; font-weight: 700; line-height: 1.15; margin-bottom: 0.75rem; }
.hero-slide .slide-desc { font-size: 1rem; color: rgba(255,255,255,0.8); margin-bottom: 1.25rem; line-height: 1.5; }
.hero-slide .slide-meta {
  display: flex; align-items: center; gap: 1.25rem;
  font-size: 0.85rem; color: rgba(255,255,255,0.7); margin-bottom: 1.5rem; flex-wrap: wrap;
}
.hero-slide .slide-meta .rating { color: var(--yellow); }
.hero-slide .slide-pricing { display: flex; align-items: baseline; gap: 0.75rem; margin-bottom: 1.5rem; }
.hero-slide .slide-pricing .sale-price { font-size: 2rem; font-weight: 700; color: var(--teal); }
.hero-slide .slide-pricing .orig-price { font-size: 1rem; text-decoration: line-through; color: rgba(255,255,255,0.5); }
.hero-slide .slide-pricing .discount-badge {
  background: var(--primary); color: var(--white); padding: 0.2rem 0.6rem;
  border-radius: 0.25rem; font-size: 0.75rem; font-weight: 700;
}
.hero-slide .slide-pricing .free-badge {
  background: var(--teal); color: var(--dark); padding: 0.2rem 0.6rem;
  border-radius: 0.25rem; font-size: 0.75rem; font-weight: 700;
}
.hero-slide .slide-image {
  flex: 1; display: flex; align-items: center; justify-content: center;
}
.hero-slide .slide-image img {
  width: 100%; max-width: 480px; border-radius: var(--radius-lg);
  box-shadow: 0 20px 60px rgba(0,0,0,0.3);
}
.hero-cta-btn {
  display: inline-flex; align-items: center; gap: 0.5rem;
  background: var(--primary); color: var(--white);
  padding: 0.75rem 1.75rem; border-radius: var(--radius);
  font-weight: 600; font-size: 0.95rem;
  transition: background var(--transition), transform 150ms ease;
}
.hero-cta-btn:hover { background: var(--primary-hover); transform: translateY(-1px); }
.carousel-nav {
  position: absolute; top: 50%; transform: translateY(-50%);
  width: 44px; height: 44px; border-radius: 50%;
  background: rgba(255,255,255,0.15); color: var(--white);
  display: flex; align-items: center; justify-content: center;
  font-size: 1.25rem; backdrop-filter: blur(4px);
  transition: background var(--transition);
  z-index: 5;
}
.carousel-nav:hover { background: rgba(255,255,255,0.3); }
.carousel-nav.prev { left: 1rem; }
.carousel-nav.next { right: 1rem; }
.carousel-dots {
  display: flex; justify-content: center; gap: 0.5rem;
  padding: 1.25rem 0; background: linear-gradient(135deg, #1a1a2e 0%, #16213e 50%, #0f3460 100%);
}
.carousel-dots .dot {
  width: 10px; height: 10px; border-radius: 50%;
  background: rgba(255,255,255,0.3); transition: background var(--transition);
}
.carousel-dots .dot.active { background: var(--white); }

/* PLACEHOLDER_COURSES */

