  display: flex; align-items: center; justify-content: center;
  font-size: 1.1rem; margin-bottom: 0.75rem;
}
.benefit-card h3 { font-size: 1rem; font-weight: 600; margin-bottom: 0.35rem; }
.benefit-card p { font-size: 0.85rem; color: var(--gray-600); line-height: 1.5; }

/* ===== CERTIFICATES ===== */
.certificates-section {
  padding: 3rem 0; background: var(--gray-100); text-align: center;
}
.cert-visual {
  max-width: 500px; margin: 0 auto;
  background: var(--white); border: 2px solid var(--gray-200);
  border-radius: var(--radius-lg); padding: 2.5rem;
  box-shadow: var(--shadow-md);
}
.cert-visual h3 { font-size: 1.1rem; font-weight: 600; margin-bottom: 0.5rem; }
.cert-visual p { font-size: 0.85rem; color: var(--gray-600); }

/* ===== FAQ ACCORDION ===== */
.faq-section { padding: 3rem 0; max-width: 800px; margin: 0 auto; }
.faq-item { border-bottom: 1px solid var(--gray-200); }
.faq-item .faq-question {
  width: 100%; display: flex; align-items: center; justify-content: space-between;
  padding: 1.25rem 0; font-size: 1rem; font-weight: 600;
  color: var(--dark); text-align: left;
  transition: color var(--transition);
}
.faq-item .faq-question:hover { color: var(--primary); }
.faq-item .faq-question .faq-icon {
  font-size: 1.25rem; transition: transform 300ms ease;
}
.faq-item.open .faq-question .faq-icon { transform: rotate(45deg); }
.faq-item .faq-answer {
  max-height: 0; overflow: hidden;
  transition: max-height 300ms ease, padding 300ms ease;
}
.faq-item.open .faq-answer { max-height: 300px; padding-bottom: 1.25rem; }
.faq-item .faq-answer p { font-size: 0.9rem; color: var(--gray-600); line-height: 1.6; }

/* ===== LOGIN PAGE ===== */
.login-page {
  min-height: 100vh; display: flex; align-items: center; justify-content: center;
  background: var(--gray-100); padding: 2rem;
}
.login-card {
  background: var(--white); border-radius: var(--radius-lg);
  padding: 2.5rem; width: 100%; max-width: 420px;
  box-shadow: var(--shadow-lg);
}
.login-card .login-logo { text-align: center; margin-bottom: 1.5rem; }
.login-card .login-logo .logo { font-size: 1.5rem; }
.login-card h1 { font-size: 1.75rem; font-weight: 700; margin-bottom: 0.35rem; }
.login-card .login-subtitle { font-size: 0.9rem; color: var(--gray-600); margin-bottom: 1.5rem; }
.social-btn {
  display: flex; align-items: center; justify-content: center; gap: 0.5rem;
  width: 100%; padding: 0.7rem; border-radius: var(--radius);
  font-size: 0.9rem; font-weight: 500; margin-bottom: 0.75rem;
  transition: opacity var(--transition);
}
.social-btn:hover { opacity: 0.9; }
.social-btn.facebook { background: #1877F2; color: var(--white); }
.social-btn.apple { background: var(--dark); color: var(--white); }
.divider {
  display: flex; align-items: center; gap: 1rem;
  margin: 1.25rem 0; color: var(--gray-400); font-size: 0.8rem;
}
.divider::before, .divider::after {
  content: ''; flex: 1; height: 1px; background: var(--gray-200);
}
.form-group { margin-bottom: 1rem; }
.form-group label {
  display: block; font-size: 0.85rem; font-weight: 500;
  color: var(--gray-700); margin-bottom: 0.35rem;
}
.form-group .input-wrapper {
  position: relative;
}
.form-group input {
  width: 100%; padding: 0.65rem 0.85rem;
  border: 1px solid var(--gray-200); border-radius: var(--radius);
  font-size: 0.9rem; color: var(--dark);
  transition: border-color var(--transition);
}
.form-group input:focus { outline: none; border-color: var(--primary); }
.form-group .toggle-pw {
  position: absolute; right: 0.75rem; top: 50%; transform: translateY(-50%);
  color: var(--gray-400); font-size: 1.1rem;
}
.forgot-link {
  display: block; text-align: right; font-size: 0.8rem;
  color: var(--primary); margin-bottom: 1.25rem;
}
.forgot-link:hover { text-decoration: underline; }
.btn-submit {
  width: 100%; padding: 0.75rem; border-radius: var(--radius);
  background: var(--primary); color: var(--white);
  font-size: 0.95rem; font-weight: 600;
  transition: background var(--transition);
}
.btn-submit:hover { background: var(--primary-hover); }
.signup-link {
  text-align: center; margin-top: 1.25rem;
  font-size: 0.85rem; color: var(--gray-600);
}
.signup-link a { color: var(--primary); font-weight: 500; }
.signup-link a:hover { text-decoration: underline; }

