/* ===== BENEFITS SECTION ===== */
.benefits-section { padding: 3rem 0; }
.benefits-grid {
  display: grid; grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
  gap: 1.5rem;
}
.benefit-card {
  padding: 1.5rem; border: 1px solid var(--gray-200);
  border-radius: var(--radius-lg);
  transition: box-shadow var(--transition);
}
.benefit-card:hover { box-shadow: var(--shadow-md); }
.benefit-card .benefit-icon {
  width: 40px; height: 40px; border-radius: var(--radius);
  background: rgba(240,45,0,0.08); color: var(--primary);
  display: flex; align-items: center; justify-content: center;
  font-size: 1.1rem; margin-bottom: 0.75rem;
}
.benefit-card h3 { font-size: 1rem; font-weight: 600; margin-bottom: 0.35rem; }
.benefit-card p { font-size: 0.85rem; color: var(--gray-600); line-height: 1.5; }

/* ===== CERTIFICATES ===== */
.certificates-section {
  padding: 3rem 0; background: var(--gray-100); text-align: center;
}
.cert-visual {
  max-width: 500px; margin: 0 auto;
  background: var(--white); border: 2px solid var(--gray-200);
  border-radius: var(--radius-lg); padding: 2.5rem;
  box-shadow: var(--shadow-md);
}
.cert-visual h3 { font-size: 1.1rem; font-weight: 600; margin-bottom: 0.5rem; }
.cert-visual p { font-size: 0.85rem; color: var(--gray-600); }

/* ===== FAQ ACCORDION ===== */
.faq-section { padding: 3rem 0; max-width: 800px; margin: 0 auto; }
.faq-item { border-bottom: 1px solid var(--gray-200); }
.faq-item .faq-question {
  width: 100%; display: flex; align-items: center; justify-content: space-between;
  padding: 1.25rem 0; font-size: 1rem; font-weight: 600;
  color: var(--dark); text-align: left;
  transition: color var(--transition);
}
.faq-item .faq-question:hover { color: var(--primary); }
.faq-item .faq-question .faq-icon {
  font-size: 1.25rem; transition: transform 300ms ease;
}
.faq-item.open .faq-question .faq-icon { transform: rotate(45deg); }
.faq-item .faq-answer {
  max-height: 0; overflow: hidden;
  transition: max-height 300ms ease, padding 300ms ease;
}
.faq-item.open .faq-answer { max-height: 300px; padding-bottom: 1.25rem; }
.faq-item .faq-answer p { font-size: 0.9rem; color: var(--gray-600); line-height: 1.6; }

