cd /app/output && python3 -c "
from html.parser import HTMLParser
import sys

class TagChecker(HTMLParser):
    def __init__(self):
        super().__init__()
        self.stack = []
        self.errors = []
    def handle_starttag(self, tag, attrs):
        void = {'area','base','br','col','embed','hr','img','input','link','meta','param','source','track','wbr'}
        if tag not in void:
            self.stack.append(tag)
    def handle_endtag(self, tag):
        if self.stack and self.stack[-1] == tag:
            self.stack.pop()
        elif tag in self.stack:
            while self.stack and self.stack[-1] != tag:
                self.errors.append(f'Unclosed: {self.stack.pop()}')
            if self.stack: self.stack.pop()

for f in ['index.html','courses.html','projects.html','plus.html','login.html']:
    checker = TagChecker()
    with open(f) as fh:
        checker.feed(fh.read())
    if checker.errors or checker.stack:
        print(f'{f}: errors={checker.errors}, unclosed={checker.stack}')
    else:
        print(f'{f}: OK')
"

